css:
/* ============================================================
 * 闁轰礁鎳庨鍌涚▔婵犳凹鏆?鐠?gugong.palace
 * 濞达絾绮庨弫銈夊春閻曞倻绐梙tml.yh-theme-gugong-palace
 * 閻犱焦宕橀鎼佹晬濮橆剦鍞褎鐟﹀﹢鐢电棯?+ 闁荤偛顦遍幏鎴︽煂閹搭垳骞㈤柛銉︾☉鐏忣垶鏌囬缁橆偨鐎殿喖绻愮粩椋庝沪閳ь剟鍨鹃弬琛″亾? *   鐎归潻闄勯悥?logo + 閻㈩垱鐗曢悺娆撳礆閸℃闅?/ 濞戞搩鍘介悥顔剧玻閸曨偄鐏欓悽顖涚墪閻℃瑩寮堕敍鍕獥 / 闁告瑥鍘栫粭鍌滄暜閺嵮呮憤婵繐绲鹃弸?/ 闁告瑥鍘栫粭鍛村炊閸濆嫮鏆扮紓鍌涚墳缁额偊宕抽妸锝傚亾? * 濠㈤€涜兌閻?/ 婵☆垼浜滅粻?/ 濞撴皜鍕焿缂佹柨顑囩划顖炴焻濮樺磭绠?CSS 闁告瑦锕㈤崳鍝勨枖閵娿儱寮抽柨娑樻綈ata URI闁挎稑顦埀? * ============================================================ */

/* ---------- 0. 閻犲鍟虫竟濠囧级?+ Flarum 闁告瑦锕㈤崳娲煂瀹ュ棙衼閻?---------- */
html.yh-theme-gugong-palace {
	--gg-red: #7a1e1e;
	--gg-red-deep: #5e1616;
	--gg-vermillion: #b23a2e;
	--gg-vermillion-bright: #c9442e;
	--gg-gold: #c9a14a;
	--gg-gold-deep: #a8842f;
	--gg-gold-light: #e6c76a;
	--gg-ivory: #f4ecd8;
	--gg-ivory-soft: #ece1c6;
	--gg-ivory-deep: #e2d4b4;
	--gg-ink: #2b2622;
	--gg-ink-soft: #5a4f44;
	--gg-muted: #8a7d6b;
	--gg-stone: #6e6358;
	--gg-glass: rgba(244, 236, 216, 0.78);
	--gg-glass-strong: rgba(244, 236, 216, 0.92);
	--gg-glass-edge: rgba(201, 161, 74, 0.42);
	--gg-shadow: 0 10px 30px rgba(94, 22, 22, 0.18), 0 2px 6px rgba(43, 38, 34, 0.08);
	--gg-radius: 14px;
	--gg-radius-sm: 8px;
	--gg-font: "PingFang SC", "Microsoft YaHei", "Hiragino Sans GB", "Segoe UI", serif;

	/* 闁搞儲绋戠亸顖滀焊閸濆嫷鍤?*/
	--gg-side-w: 252px;
	--gg-list-w: 380px;
	--gg-header-h: 54px;
	--gg-gap: 14px;

	/* 闁告牞妗ㄧ紞鍛村锤閹邦厾鍨?*/
	--gg-mid-left: calc(var(--gg-side-w) + var(--gg-gap));
	--gg-right-left: calc(var(--gg-side-w) + var(--gg-gap) + var(--gg-list-w) + var(--gg-gap));
	--gg-content-top: calc(var(--gg-header-h) + var(--gg-gap));
	--gg-content-bottom: var(--gg-gap);

	/* Flarum 閻犱焦宕橀鍛婄閵堝洤顤?-> 闁轰礁鎳庨鍌炴嚌?*/
	--primary-color: #b23a2e;
	--secondary-color: #c9a14a;
	--body-bg: transparent;
	--body-bg-shaded: rgba(244, 236, 216, 0.6);
	--body-bg-light: rgba(244, 236, 216, 0.85);
	--body-bg-faded: rgba(244, 236, 216, 0.72);
	--text-color: #2b2622;
	--heading-color: #7a1e1e;
	--link-color: #a8342a;
	--muted-color: #8a7d6b;
	--muted-color-light: #a89a86;
	--muted-more-color: #b8ab97;
	--control-bg: rgba(244, 236, 216, 0.8);
	--control-bg-light: rgba(244, 236, 216, 0.94);
	--control-bg-shaded: rgba(178, 58, 46, 0.1);
	--control-color: #2b2622;
	--shadow-color: rgba(94, 22, 22, 0.2);
	--header-bg: transparent;
	--header-color: #f4ecd8;
	--header-colored-color: #f4ecd8;
	--header-colored-control-color: #f4ecd8;
	--header-colored-control-bg: rgba(244, 236, 216, 0.18);
	--header-colored-control-bg-shaded: rgba(244, 236, 216, 0.3);
	--header-colored-control-bg-fadedin: rgba(201, 161, 74, 0.2);
	--hero-bg: transparent;
	--hero-color: #7a1e1e;
	--discussion-title-color: #7a1e1e;
	--discussion-list-item-bg-hover: rgba(178, 58, 46, 0.1);
	--button-color: #2b2622;
	--button-bg: rgba(244, 236, 216, 0.9);
	--button-bg-hover: #f0e6cc;
	--button-bg-active: #ece1c6;
	--button-primary-color: #fff7e6;
	--button-primary-bg: #b23a2e;
	--button-primary-bg-hover: #c9442e;
	--button-primary-bg-active: #962f24;
	--overlay-bg: rgba(43, 22, 16, 0.5);
	--code-bg: rgba(226, 212, 180, 0.6);
	--code-color: #2b2622;
	--border-radius: 10px;
	--zindex-header: 1000;
	--zindex-modal: 1700;

	--header-height: calc(var(--gg-header-h) + 12px);
	--header-height-phone: calc(var(--gg-header-h) + 8px);
}

/* ---------- 1. 濡炪倗鏁诲鐗堟償閺囶亞绐楅悗鐧哥悼閻掑﹥绔熸担铏瑰墾 + 闁荤偛顦遍幏鎴﹀礂?---------- */
html.yh-theme-gugong-palace,
html.yh-theme-gugong-palace body {
	min-height: 100%;
}

html.yh-theme-gugong-palace body {
	font-family: var(--gg-font);
	color: var(--gg-ink);
	background:
		linear-gradient(108deg, rgba(244, 236, 216, 0.92) 0%, rgba(236, 225, 198, 0.7) 45%, rgba(244, 236, 216, 0.3) 100%),
		var(--gg-bg, linear-gradient(135deg, #f4ecd8, #ece1c6));
	background-attachment: fixed;
	background-size: cover;
	background-position: center;
	background-repeat: no-repeat;
	overflow: hidden;
}

html.yh-theme-gugong-palace body::before {
	content: "";
	position: fixed;
	inset: 0;
	z-index: 0;
	pointer-events: none;
	background:
		radial-gradient(ellipse 48% 38% at 16% 16%, rgba(201, 161, 74, 0.22), transparent 70%),
		radial-gradient(ellipse 40% 34% at 90% 86%, rgba(94, 22, 22, 0.14), transparent 68%);
}

html.yh-theme-gugong-palace #app.App {
	position: relative;
	z-index: 1;
	min-height: 100vh;
	padding: 0 !important;
	background: transparent !important;
}

/* ---------- 2. 濡炪倛鍩栭悥顕€鏁嶅顒夊敨濠⒀勭懄婵垹顬婇幇鍓佺鐎归潻濡囬顒佺▔?logo 闁哄秶銆嬬槐娆戔偓闈涚秺缂嶅牆顔忛敂鐣屽焿闁?---------- */
html.yh-theme-gugong-palace .App-navigation {
	display: none !important;
}

html.yh-theme-gugong-palace .App-drawer {
	position: static !important;
	width: auto !important;
	transform: none !important;
	visibility: visible !important;
	background: transparent !important;
	box-shadow: none !important;
	z-index: auto !important;
}

html.yh-theme-gugong-palace .App-header {
	position: fixed !important;
	top: 0 !important;
	left: 0 !important;
	right: 0 !important;
	z-index: 1200 !important;
	height: var(--gg-header-h) !important;
	padding: 0 !important;
	border: 0 !important;
	box-sizing: border-box;
	background:
		linear-gradient(90deg, var(--gg-red-deep) 0%, var(--gg-red) 38%, var(--gg-red-deep) 100%),
		var(--gg-top-image, none) !important;
	background-size: cover, auto 220% !important;
	background-position: center, right -10% center !important;
	background-repeat: no-repeat !important;
	box-shadow: 0 6px 20px rgba(94, 22, 22, 0.28) !important;
	color: var(--gg-ivory) !important;
}

html.yh-theme-gugong-palace .App-header::after {
	content: "";
	position: absolute;
	left: 0;
	right: 0;
	bottom: 0;
	height: 3px;
	background: linear-gradient(90deg, var(--gg-gold-deep), var(--gg-gold-light), var(--gg-gold), var(--gg-gold-deep));
	opacity: 0.95;
	pointer-events: none;
}

html.yh-theme-gugong-palace .App-header .container {
	position: relative;
	width: auto !important;
	max-width: none !important;
	height: 100%;
	margin: 0 !important;
	padding: 0 var(--gg-gap) 0 0 !important;
	display: flex !important;
	align-items: center;
	gap: 10px;
	flex-wrap: nowrap;
	overflow: visible;
}

/* logo 闁哄秶銆嬬槐浼村础閻樺啿绁﹀銈堝煐閻栴噣寮甸埀顒€顔忛敂鑲╃閻庣妫勭€瑰磭鈧潧缍婄紞鍫濐啅閿旂晫鍩夐柨娑樺缂嶆梹绋夐幁鎺嗗亾瀹€鈧鍥ㄧ▔閳ь剟寮借箛瀣у亾瀹ュ洦鐣卞銈呯埣閸?*/
html.yh-theme-gugong-palace .Header-title {
	position: absolute !important;
	left: 0;
	top: 0;
	width: var(--gg-side-w);
	height: 100%;
	margin: 0 !important;
	padding: 0 16px !important;
	display: flex !important;
	align-items: center;
	justify-content: center;
	gap: 8px;
	line-height: 1;
	font-weight: 800;
	letter-spacing: 0.16em;
	border-right: 2px solid var(--gg-gold);
	box-sizing: border-box;
	overflow: hidden;
}

html.yh-theme-gugong-palace .Header-title a {
	color: var(--gg-gold-light) !important;
	text-shadow: 0 1px 0 rgba(94, 22, 22, 0.6);
	display: inline-flex;
	align-items: center;
	gap: 8px;
}

html.yh-theme-gugong-palace .Header-logo {
	max-height: 26px;
	filter: drop-shadow(0 1px 2px rgba(201, 161, 74, 0.45)) brightness(1.08);
}

/* logo 闁哄秹妫跨粻锝夊触鎼达絾鐣卞☉鎾诡嚙椤曢亶鎳?/ 闁瑰吋绮庨崒?/ 闁活潿鍔嶉崺娑㈠礌鏉炴壆鐭ょ€归潻闄勯悥顕€宕ｉ崗鍛珷鐎殿喒鍋撳┑?*/
html.yh-theme-gugong-palace .App-header .container > .Header-primary {
	margin-left: calc(var(--gg-side-w) + var(--gg-gap)) !important;
}

html.yh-theme-gugong-palace .Header-primary {
	float: none !important;
	flex: 1 1 auto;
	min-width: 0;
}

html.yh-theme-gugong-palace .Header-secondary {
	float: none !important;
	margin-left: auto !important;
	flex: 0 0 auto;
}

html.yh-theme-gugong-palace .App-header a,
html.yh-theme-gugong-palace .App-header .Button {
	color: var(--gg-ivory) !important;
	text-shadow: none !important;
}

html.yh-theme-gugong-palace .App-header .Button {
	border-color: rgba(244, 236, 216, 0.28) !important;
	background: rgba(244, 236, 216, 0.12) !important;
}

html.yh-theme-gugong-palace .App-header .Button:hover {
	background: rgba(201, 161, 74, 0.28) !important;
	border-color: rgba(201, 161, 74, 0.55) !important;
}

html.yh-theme-gugong-palace .Header-controls {
	display: flex;
	align-items: center;
	gap: 4px;
	margin: 0;
	padding: 0;
	list-style: none;
}

html.yh-theme-gugong-palace .Header-controls > li {
	padding: 0 2px;
	float: none !important;
}

html.yh-theme-gugong-palace .App-header .Search-input .FormControl {
	background: rgba(244, 236, 216, 0.16) !important;
	border-color: rgba(201, 161, 74, 0.4) !important;
	color: var(--gg-ivory) !important;
}

html.yh-theme-gugong-palace .App-header .Search-input .FormControl::placeholder {
	color: rgba(244, 236, 216, 0.65);
}

/* ---------- 3. 閸愬懎顔愰崠鐚寸窗閸ユ稑灏崶鍝勭暰妤犮劍鐏?---------- */
html.yh-theme-gugong-palace .App-content {
	min-height: 0 !important;
	height: auto !important;
	margin: 0 !important;
	padding: var(--gg-content-top) var(--gg-gap) var(--gg-content-bottom) var(--gg-mid-left) !important;
	border: 0 !important;
	background: transparent !important;
	box-shadow: none !important;
}

html.yh-theme-gugong-palace .App-content > .container,
html.yh-theme-gugong-palace .App-content .container {
	max-width: none !important;
	padding-left: 0 !important;
	padding-right: 0 !important;
}

/* ---------- 3a. 瀹革附鐖敍姘瀻閸栧搫顕遍懜顏庣礉閸ュ搫鐣鹃崗銊╃彯閿涘澓-index 閺堚偓妤傛﹫绱濆闀愮瑝鐞氼偉顩惄鏍电礆 ---------- */
html.yh-theme-gugong-palace .sideNavContainer {
	display: block !important;
	position: relative;
}

html.yh-theme-gugong-palace .sideNav,
html.yh-theme-gugong-palace .IndexPage-nav.sideNav,
html.yh-theme-gugong-palace .DiscussionPage-nav,
html.yh-theme-gugong-palace .TagsPage .sideNav {
	position: fixed !important;
	top: var(--gg-header-h) !important;
	left: 0 !important;
	bottom: 0 !important;
	width: var(--gg-side-w) !important;
	min-width: var(--gg-side-w) !important;
	max-width: var(--gg-side-w) !important;
	margin: 0 !important;
	padding: 14px 12px 24px !important;
	z-index: 1100 !important;
	float: none !important;
	overflow-x: hidden !important;
	overflow-y: auto !important;
	white-space: normal !important;
	box-sizing: border-box;
	isolation: isolate;
	background:
		linear-gradient(180deg, rgba(122, 30, 30, 0.97) 0%, rgba(94, 22, 22, 0.97) 60%, rgba(78, 16, 16, 0.97) 100%),
		var(--gg-nav, none) !important;
	background-size: auto, auto 360px !important;
	background-position: 0 0, 50% bottom !important;
	background-repeat: no-repeat !important;
	border: 0 !important;
	border-right: 2px solid var(--gg-gold) !important;
	box-shadow: 6px 0 24px rgba(94, 22, 22, 0.22) !important;
}

html.yh-theme-gugong-palace .sideNav::after,
html.yh-theme-gugong-palace .IndexPage-nav.sideNav::after,
html.yh-theme-gugong-palace .DiscussionPage-nav::after,
html.yh-theme-gugong-palace .TagsPage .sideNav::after {
	display: none !important;
}

/* Flarum 閸︺劍鐖ｇ粵楣冦€夐幎?sideNav 閺€瑙勫灇濡亜鎮滈弽鍥╊劮閺夆槄绱卞鍝勫煑閸ㄥ倻娲块敍灞煎▏瀹革附鐖崷銊︾垼缁涢箖銆夋稊鐔稿灇缁?*/
html.yh-theme-gugong-palace .TagsPage .sideNav {
	white-space: normal !important;
	overflow-x: hidden !important;
	overflow-y: auto !important;
}
html.yh-theme-gugong-palace .TagsPage .sideNav > ul > li,
html.yh-theme-gugong-palace .TagsPage .sideNav .Dropdown-menu > li {
	display: block !important;
	width: 100% !important;
	margin: 0 0 6px !important;
	float: none !important;
	vertical-align: top !important;
}
html.yh-theme-gugong-palace .TagsPage .sideNav > ul > li:first-child {
	width: 100% !important;
}

html.yh-theme-gugong-palace .sideNav > ul,
html.yh-theme-gugong-palace .sideNav > ul.affix {
	width: 100% !important;
	margin: 0 !important;
	padding: 0 !important;
	position: static !important;
	top: auto !important;
	list-style: none;
}

html.yh-theme-gugong-palace .sideNav > ul > li,
html.yh-theme-gugong-palace .sideNav .Dropdown-menu > li {
	display: block !important;
	margin: 0 0 6px !important;
	width: 100% !important;
	float: none !important;
}

html.yh-theme-gugong-palace .sideNav .Dropdown--select {
	display: block !important;
	width: 100%;
}

html.yh-theme-gugong-palace .sideNav .Dropdown--select .Dropdown-toggle {
	display: none !important;
}

html.yh-theme-gugong-palace .sideNav .Dropdown--select .Dropdown-menu {
	display: block !important;
	position: static !important;
	float: none !important;
	width: 100% !important;
	min-width: 0 !important;
	margin: 0 !important;
	padding: 0 !important;
	border: 0 !important;
	background: transparent !important;
	box-shadow: none !important;
}

html.yh-theme-gugong-palace .sideNav .Dropdown-menu > li > a,
html.yh-theme-gugong-palace .sideNav .Dropdown--select .Dropdown-menu > li > a {
	display: block !important;
	padding: 9px 12px 9px 14px !important;
	border-radius: var(--gg-radius-sm) !important;
	color: var(--gg-ivory) !important;
	font-weight: 600;
	letter-spacing: 0.02em;
	transition: background 0.18s ease, color 0.18s ease, transform 0.18s ease;
}

html.yh-theme-gugong-palace .sideNav .Dropdown-menu > li > a:hover,
html.yh-theme-gugong-palace .sideNav .Dropdown--select .Dropdown-menu > li > a:hover {
	background: rgba(201, 161, 74, 0.22) !important;
	color: var(--gg-gold-light) !important;
	text-decoration: none !important;
	transform: translateX(2px);
}

html.yh-theme-gugong-palace .sideNav .Dropdown-menu > li.active > a,
html.yh-theme-gugong-palace .sideNav .Dropdown--select .Dropdown-menu > li.active > a {
	background: linear-gradient(90deg, var(--gg-vermillion), var(--gg-gold-deep)) !important;
	color: #fff7e6 !important;
	font-weight: 700 !important;
	box-shadow: 0 4px 14px rgba(178, 58, 46, 0.4);
	border-left: 3px solid var(--gg-gold-light);
}

html.yh-theme-gugong-palace .item-newDiscussion .Button,
html.yh-theme-gugong-palace .sideNav .item-newDiscussion .Button {
	width: 100%;
	border-radius: var(--gg-radius-sm) !important;
	font-weight: 700;
	letter-spacing: 0.04em;
	box-shadow: 0 6px 18px rgba(178, 58, 46, 0.32) !important;
}

/* 鐠併劏顔戞い闈涗箯閺嶅繑鏂佸Δ鐓庣湴鐎规矮缍呴崳顭掔礄閸掑棗灏崚妤勩€冮崷銊ョ瑯鐎涙劙銆?Flarum 娑撳秵瑕嗛弻鎿勭礆 */
html.yh-theme-gugong-palace .DiscussionPage-nav > ul {
	padding: 0;
	margin: 0;
	list-style: none;
}

html.yh-theme-gugong-palace .DiscussionPage-nav .Scrubber a {
	color: var(--gg-gold-light) !important;
	font-weight: 600;
}

/* Keep the inbox navigation outside Flarum's page subtree on desktop. */
html.yh-theme-gugong-palace:has([data-yh-layout-portal="gugong.palace:primary-nav"]) .DiscussionPage-nav {
	display: none !important;
}

html.yh-theme-gugong-palace .DiscussionPage-nav .Scrubber-scrollbar {
	background:
		linear-gradient(180deg, rgba(244, 236, 216, 0.22), rgba(201, 161, 74, 0.18)),
		repeating-linear-gradient(180deg, rgba(201, 161, 74, 0.1) 0 2px, transparent 2px 6px);
	border: 1px solid rgba(201, 161, 74, 0.35);
	border-radius: 999px;
	margin: 10px 0 !important;
	overflow: hidden;
}

html.yh-theme-gugong-palace .Scrubber-bar {
	background: linear-gradient(180deg, var(--gg-gold-light), var(--gg-gold), var(--gg-vermillion)) !important;
	border-radius: 999px;
	box-shadow: 0 0 10px rgba(201, 161, 74, 0.5);
}

html.yh-theme-gugong-palace .Scrubber-handle {
	color: var(--gg-gold-light);
}
/* ---------- 3b. 娑擃厽鐖敍姘瑯鐎涙劖娼惄顕嗙礄缁愬嫬鍨敍灞芥祼鐎规熬绱濋崘鍛村劥濠婃艾濮╅敍?---------- */
/* 妫ｆ牠銆夐悽?.IndexPage-results閿涙稒鐖ｇ粵楣冦€夐敍鍫㈠仯閸掑棗灏崥搴礆閻?.sideNavOffset閿涙稑绗樼€涙劙銆夐悽?.DiscussionPage-list */
html.yh-theme-gugong-palace .IndexPage-results,
html.yh-theme-gugong-palace .IndexPage .sideNavOffset,
html.yh-theme-gugong-palace .TagsPage .sideNavOffset,
html.yh-theme-gugong-palace .DiscussionPage-list {
	position: fixed !important;
